-- MÓDULO 3-1: Triggers
-- ==========================================

CREATE OR REPLACE FUNCTION auditar_creditos()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.creditos < OLD.creditos THEN
        RAISE NOTICE '¡Alerta! Piloto % perdió créditos.', NEW.nombre;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- RETO: Crea un TRIGGER llamado 'trg_auditar_creditos'
-- que se ejecute BEFORE UPDATE en la tabla pilotos
-- e invoque la función auditar_creditos().

3-2.content:
-- ==========================================
-- MÓDULO 3-2: Funciones (PL/pgSQL)
-- ==========================================

CREATE OR REPLACE FUNCTION pagar_recompensa(p_id INTEGER, monto NUMERIC)
RETURNS VOID AS $$
BEGIN
    UPDATE pilotos SET creditos = creditos + monto WHERE id = p_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Piloto % no encontrado', p_id;
    END IF;
END;
$$ LANGUAGE plpgsql;

-- RETO: Llama a la función usando SELECT o PERFORM para 
-- darle 5000 créditos al piloto con ID 1.

